"""
NCERT Class 5 Science Chapter 7: Energy - How Things Work Data
"""

CHAPTER_META = {'chapter_num': 7, 'title': 'Energy - How Things Work', 'class_level': 'Class 5', 'subject': 'Science (Curiosity, NEP 2020)', 'description': 'NCERT Class 5 Science Chapter 7: Energy - How Things Work interactive animated laboratory.'}

SLIDES = [{'id': 1, 'title': 'What Energy Does', 'subtitle': 'Definition: Movement, Light, Sound, Work & Thermal Changes', 'concept_html': '\n            <p>Every single activity in our bustling world requires <strong>energy</strong>. From a soaring eagle and a speeding school bus to the gentle flicker of a bedside lamp and the warmth of a morning cup of milk, energy is the fundamental driving force of nature.</p>\n            <div class="p-3.5 my-3 rounded-2xl bg-amber-950/40 border border-amber-500/40">\n                <span class="text-xs font-bold text-amber-300 block mb-1">Scientific Definition of Energy:</span>\n                <p class="text-xs text-slate-200 leading-relaxed">\n                    <strong>Energy</strong> is defined in physical science as the capacity or ability to do work, make things move, produce light or sound, and cause temperature changes. Whenever anything happens in the universe, energy is being used or transformed!\n                </p>\n            </div>\n            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2.5 my-3 text-xs text-center">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-lg block mb-1">🏃</span>\n                    <span class="font-bold text-cyan-400 block">Movement</span>\n                    <span class="text-slate-400 text-[10px]">Kinetic action of moving bodies</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-lg block mb-1">💡</span>\n                    <span class="font-bold text-amber-400 block">Light</span>\n                    <span class="text-slate-400 text-[10px]">Radiant waves illuminating space</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-lg block mb-1">🔔</span>\n                    <span class="font-bold text-purple-400 block">Sound</span>\n                    <span class="text-slate-400 text-[10px]">Pressure vibrations through air</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-lg block mb-1">🔥</span>\n                    <span class="font-bold text-rose-400 block">Thermal</span>\n                    <span class="text-slate-400 text-[10px]">Heat raising particle temperatures</span>\n                </div>\n            </div>\n            <p>Energy cannot be seen directly, but its effects are unmistakably visible. When leaves rustle in the breeze, wind energy is pushing them; when water boils on a stove, thermal energy is speeding up water molecules.</p>\n        ', 'spoken_text': 'Welcome young scientists to Chapter 7: Energy, How Things Work! Look around your room right now. What makes the ceiling fan rotate, the bulb glow with bright light, or your smartphone chime with ringtones? It is energy! In science, energy is defined as the capacity to do work, create motion, generate sound, emit light, and change temperature. While we cannot hold energy in our hands like a pebble, we observe its incredible power whenever objects accelerate, warm up, or illuminate our surroundings.', 'lecture_script': 'Introduces the scientific definition of energy as the capacity to cause motion, work, light, sound, and thermal changes, connecting everyday phenomena to energy manifestations.', 'checkpoints': [{'question': 'Which of the following is the most scientifically accurate definition of energy?', 'options': ['A visible liquid stored inside power stations', 'The capacity to do work, cause movement, or produce heat, light, and sound', 'A chemical substance found only in petroleum', 'A force that only acts during the daytime'], 'correct': 1, 'explanation': 'Energy is fundamentally defined as the ability or capacity to perform work, create motion, or produce light, sound, and thermal changes.', 'study_insight': 'Although energy takes many forms such as kinetic, chemical, and electrical, it is governed by the Law of Conservation of Energy: energy cannot be created or destroyed, only changed from one form to another.'}, {'question': 'When a ringing school bell vibrates and sends chime notes across the playground, which form of energy is reaching your ears?', 'options': ['Sound energy travelling as pressure waves through air', 'Magnetic energy flowing through the ground', 'Nuclear energy radiated from the sun', 'Chemical energy stored in brass metal'], 'correct': 0, 'explanation': 'Striking the bell causes it to vibrate rapidly, transferring mechanical vibrations into air molecules as sound waves that stimulate our eardrums.', 'study_insight': 'Sound cannot travel through a vacuum; it requires a physical medium such as air, water, or solid metal to propagate its energy waves.'}]}, {'id': 2, 'title': 'Balloon Rocket', 'subtitle': 'Activity 1: Stored Elastic Energy Converted into Forward Thrust', 'concept_html': '\n            <p>How does stored energy produce rapid forward motion? In <strong>Activity 1: The Balloon Air Rocket</strong>, we explore how trapped, pressurized air can propel an object across a room along a guide string.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🎈 Stored Elastic Energy</span>\n                    <p class="text-xs text-slate-300">\n                        Blowing air into a rubber balloon forces its elastic walls to stretch outward. The compressed air molecules inside are pushed closer together, storing <strong>elastic potential energy</strong> under pressure.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🚀 Action and Reaction Thrust</span>\n                    <p class="text-xs text-slate-300">\n                        When the balloon neck is released, the stretched rubber snaps back, forcing compressed air backward at high speed. Following Newton\'s law of motion, the escaping backward jet produces an equal forward push (thrust) that shoots the balloon rocket forward along the taut straw guide!\n                    </p>\n                </div>\n            </div>\n            <p>This simple classroom experiment mirrors the exact engineering propulsion principle that launches modern ISRO space launch vehicles like the PSLV and LVM3 into orbit!</p>\n        ', 'spoken_text': 'Let us examine Activity 1: The Balloon Air Rocket. When we blow breath into a rubber balloon, the rubber skin stretches taut. Stored elastic potential energy builds up within the trapped, compressed air. Now, tape that balloon to a drinking straw threaded along a smooth horizontal string. What happens the moment you let go of the nozzle? The pressurized air rushes backward in a furious jet! That backward rush exerts an equal and opposite forward reaction force, shooting your balloon rocket whizzing across the room! This exact rocket thrust mechanism powers satellites into outer space.', 'lecture_script': 'Explains Activity 1 Balloon Rocket experiment, demonstrating the conversion of stored elastic potential energy into kinetic motion via backward air jet action and forward reaction thrust.', 'checkpoints': [{'question': 'What form of energy is stored inside an inflated, stretched balloon before its nozzle is released?', 'options': ['Electrical energy stored in copper wires', 'Elastic potential energy in the stretched rubber and compressed air', 'Nuclear energy in atomic cores', 'Thermal energy from boiling water'], 'correct': 1, 'explanation': 'Inflating the balloon stretches its rubber molecules and compresses air particles inside, storing elastic potential energy waiting to be released.', 'study_insight': 'Potential energy is stored energy possessed by an object due to its position, compression, or chemical state.'}, {'question': 'Why does the balloon rocket zoom forward when air rushes backward out of its open nozzle?', 'options': ['Because warm air is attracted to the opposite wall', 'Because the escaping backward air stream creates an equal and opposite forward push', 'Because gravity pulls the balloon sideways', 'Because the string pulls the straw magnetically'], 'correct': 1, 'explanation': 'According to the principle of action and reaction, as air exhausts backward with force, an opposing reactive thrust propels the rocket assembly forward.', 'study_insight': 'This physical action-reaction principle governs rocket engines, jet aeroplanes, and even the propulsion of swimming squids in the ocean.'}]}, {'id': 3, 'title': 'Vibrating Strings', 'subtitle': 'Activity 2: Rubber Band Guitars & Sound Energy Wave Physics', 'concept_html': '\n            <p>Sound is not magical; it is pure mechanical energy in rapid motion. In <strong>Activity 2: The Rubber Band Guitar</strong>, students stretch rubber bands of varying widths across an empty shoebox or hollow cardboard container.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-purple-400 block mb-1">🎸 Plucking and Mechanical Vibration</span>\n                    <p class="text-xs text-slate-300">\n                        When you pull and release a stretched rubber band, you supply mechanical kinetic energy. The band oscillates rapidly back and forth in a blurry vibration, colliding with adjacent air molecules thousands of times every second.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🔊 Resonance Chamber Amplification</span>\n                    <p class="text-xs text-slate-300">\n                        A thin rubber band vibrating alone in open air produces a faint hum. But when mounted over an open cardboard box, the vibrating band sets the enclosed column of air into sympathetic resonance, dramatically amplifying the volume into clear, musical notes!\n                    </p>\n                </div>\n            </div>\n            <p>Tighter and thinner rubber bands vibrate faster (higher frequency), generating a high-pitched sharp note, whereas looser, thicker bands oscillate more slowly, creating deep bass vibrations.</p>\n        ', 'spoken_text': 'Now let us construct Activity 2: The Rubber Band Guitar. Take an empty cardboard shoebox and stretch three different rubber bands across its open top: one thin, one medium, and one thick. When you pluck a band with your fingertip, your finger delivers mechanical energy. Watch closely: the rubber band blurs as it vibrates back and forth! Each rapid vibration strikes neighboring air molecules, sending invisible pressure waves rippling across the room into your ears. Notice that tighter, thinner bands vibrate faster to produce high-pitched notes, while thick bands vibrate slowly to produce deep tones.', 'lecture_script': 'Covers Activity 2 Rubber Band Guitars, detailing how mechanical plucking generates acoustic sound energy through high-frequency vibrations and cardboard chamber resonance.', 'checkpoints': [{'question': 'What physical motion must occur in an object for it to produce sound energy?', 'options': ['It must undergo rapid back-and-forth vibrations', 'It must completely melt into a liquid', 'It must be painted in bright primary colours', 'It must remain perfectly motionless'], 'correct': 0, 'explanation': 'All sound originates from mechanical vibrations. As an object vibrates, it repeatedly compresses and rarefies surrounding air particles, creating sound waves.', 'study_insight': 'Placing your fingers gently against your throat while humming lets you directly feel the vibrations of your vocal cords producing sound energy.'}, {'question': 'In the rubber band guitar experiment, how does stretching a rubber band tighter change the musical note it produces?', 'options': ['It stops vibrating completely', 'It vibrates faster, creating a higher-pitched sound', 'It turns the sound into green light', 'It produces a lower bass rumble'], 'correct': 1, 'explanation': 'Increasing tension causes the rubber band to oscillate at a higher frequency (more cycles per second), resulting in a noticeably higher pitch.', 'study_insight': 'Musicians tuning a violin, sitar, or guitar tighten peg keys to raise pitch and loosen them to lower pitch based on this identical physics principle.'}]}, {'id': 4, 'title': 'Warming Sun', 'subtitle': 'Activity 3: Solar Radiation Absorption & Thermal Temperature Rise', 'concept_html': '\n            <p>The primary source of nearly all energy on planet Earth is the blazing Sun located 150 million kilometres away. In <strong>Activity 3: Warming Water in the Sun</strong>, students measure solar radiant energy directly.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">☀️ Radiant Heat Transfer</span>\n                    <p class="text-xs text-slate-300">\n                        Fill two identical bowls with equal amounts of room-temperature tap water (say, 24°C). Place Bowl A in a cool, shaded classroom cupboard and place Bowl B outside under open, direct sunshine.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🌡️ Molecular Kinetic Warming</span>\n                    <p class="text-xs text-slate-300">\n                        After two hours, dip a laboratory thermometer into both bowls. Bowl A remains at 24°C, but Bowl B has warmed to 38°C! Solar light rays carrying radiant energy were absorbed by the water, speeding up its molecules and raising its temperature.\n                    </p>\n                </div>\n            </div>\n            <p>Dark or black-bottomed containers absorb solar heat even more aggressively than light, reflective silver surfaces, demonstrating how radiant energy converts directly into thermal heat.</p>\n        ', 'spoken_text': 'Observe Activity 3: Warming Water in the Sun. Imagine placing two identical metal bowls filled with fresh tap water at room temperature. Keep one bowl inside a cool shaded cupboard, and place the other outdoors directly under blazing afternoon sunshine. Two hours later, touch the water in both bowls! The bowl kept in the cupboard is still cool, while the bowl under the sun is distinctly warm. Why? Because the Sun continuously beams radiant light and infrared energy across 150 million kilometres of empty space. As water absorbs this radiant energy, its molecules jiggle faster, causing a measurable rise in thermal temperature!', 'lecture_script': 'Explores Activity 3, showing how radiant solar energy travels through space, is absorbed by matter like water, and converts directly into internal thermal energy.', 'checkpoints': [{'question': 'What happens to the molecules of water inside a bowl as it absorbs thermal energy from the Sun?', 'options': ['They jiggle and move faster, causing the water temperature to rise', 'They freeze into solid crystal cubes', 'They lose all their electrical charge and vanish', 'They slow down until they become completely motionless'], 'correct': 0, 'explanation': 'Temperature is a measure of the average kinetic energy of molecules. Absorbing solar thermal energy causes water molecules to jiggle and move faster.', 'study_insight': 'Heat always flows spontaneously from a warmer object to a cooler object until thermal equilibrium is established.'}, {'question': 'Why do traditional rooftop solar water heaters use black-painted metal tubes instead of white tubes?', 'options': ['Black surfaces absorb radiant solar heat much more effectively than reflective white surfaces', 'Black paint prevents water from leaking', 'Black tubes weigh less than white tubes', 'Black paint makes the water taste sweet'], 'correct': 0, 'explanation': 'Dark, matte black surfaces absorb virtually all incoming wavelengths of visible and infrared solar radiation, converting them efficiently into heat.', 'study_insight': 'Wearing dark clothes in peak summer feels much warmer because dark pigments absorb solar radiant energy rather than reflecting it away.'}]}, {'id': 5, 'title': 'Food Battery', 'subtitle': 'Chemical Energy Storage: Human Metabolism & Biological Energy Reserves', 'concept_html': '\n            <p>Every living creature—from an energetic child sprinting across a football field to a chirping sparrow—requires constant energy. Where does biological energy come from? From the <strong>food we eat</strong>!</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🍎 Chemical Energy in Nutrients</span>\n                    <p class="text-xs text-slate-300">\n                        Grains (rotis, rice), pulses (dal), vegetables, and fruits contain <strong>chemical energy</strong> synthesized by green plants through photosynthesis. When we chew and digest food, enzymes break down complex carbohydrates into simple glucose sugars.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🔋 The Living Battery Storage</span>\n                    <p class="text-xs text-slate-300">\n                        Our bodies do not consume all energy immediately. Just like rechargeable electronic batteries store chemical charge, our liver and muscles store surplus glucose as <strong>glycogen</strong> and body fat, releasing energy steadily as we walk, study, and breathe throughout the night!\n                    </p>\n                </div>\n            </div>\n            <p>Without regular food intake, our biological battery runs low: we feel sluggish, weak, and tired because our cells lack fuel to power cellular respiration.</p>\n        ', 'spoken_text': 'Think about your own daily energy. How do you sprint across the playground, solve math puzzles, or keep your heart beating 24 hours a day? You run on food energy! Plants harness sunlight to create carbohydrates, proteins, and fats packed with chemical energy. When we consume rotis, fruits, and dal, our digestive system breaks these down. Inside every living cell, glucose reacts with inhaled oxygen to release mechanical energy for our muscles and heat energy to keep our body at a steady 37 degrees Celsius. Our liver and muscles act just like rechargeable batteries, storing surplus energy so we can stay active even between meals!', 'lecture_script': 'Explains food as the primary source of biological chemical energy, cellular respiration with oxygen, and internal glycogen/fat reserves acting like rechargeable batteries.', 'checkpoints': [{'question': 'What type of energy is stored inside the rice, rotis, fruits, and vegetables we eat daily?', 'options': ['Chemical energy bound in nutrient molecules', 'Electrical energy circulating along cables', 'Sound energy trapped inside seeds', 'Nuclear energy in atomic reactors'], 'correct': 0, 'explanation': 'Food stores chemical potential energy within the atomic bonds of carbohydrates, proteins, and lipids, created originally by plants using sunlight.', 'study_insight': 'Food energy is measured in units called Calories or Joules; 1 kilocalorie equals approximately 4,184 Joules of mechanical work!'}, {'question': 'How does the human body resemble a rechargeable battery in how it manages energy?', 'options': ['It has metal terminals sticking out of the head', 'It stores surplus energy from food in muscles and liver for later use during activity and sleep', 'It only functions when plugged into an electrical wall socket', 'It never requires any food or water'], 'correct': 1, 'explanation': 'The human body stores excess chemical energy as glycogen in the liver and muscles, as well as adipose fat tissue, discharging it whenever energy is needed.', 'study_insight': 'Even during sound sleep, our body consumes significant energy to keep the brain dreaming, the lungs inhaling, and the heart pumping blood.'}]}, {'id': 6, 'title': 'Fuel Power', 'subtitle': 'Combustion Engines: Petrol, Diesel, Cooking Gas (LPG) & Coal', 'concept_html': '\n            <p>Just as human bodies burn food to move, human machines burn <strong>fuels</strong> to perform heavy mechanical work. A fuel is any substance that releases useful thermal energy when burned (combusted) with oxygen.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-3 gap-2.5 my-3 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-cyan-400 block mb-1">🚗 Transport Fuels</span>\n                    <span class="text-slate-300"><strong>Petrol & Diesel:</strong> Liquid petroleum fractions refined from crude oil that power cars, trucks, trains, and tractors.</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-amber-400 block mb-1">🍳 Domestic Cooking</span>\n                    <span class="text-slate-300"><strong>LPG (Liquefied Petroleum Gas):</strong> Pressurized gas cylinders powering kitchen stoves cleanly and instantly.</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-rose-400 block mb-1">🏭 Industrial Power</span>\n                    <span class="text-slate-300"><strong>Coal & Natural Gas:</strong> Fossil fuels burned inside thermal power stations to generate high-pressure steam for turbines.</span>\n                </div>\n            </div>\n            <p>Inside an automobile\'s engine cylinder, tiny droplets of petrol are mixed with air and ignited by a spark plug. The rapid combustion causes gas to expand explosively, pushing the metal piston down and spinning the vehicle\'s wheels!</p>\n        ', 'spoken_text': 'Consider the vehicles on our roads. A motorbike or a school bus cannot run on apples or rice; it requires fuel! Fuels like petrol, diesel, compressed natural gas, and liquefied cooking gas are rich in chemical energy formed millions of years ago. Inside an engine cylinder, a tiny mist of petrol is mixed with air and ignited with a spark. The fuel burns instantly, generating super-hot, expanding gases that push the engine pistons with immense force. That piston thrust spins the crankshaft, turns the wheels, and carries passengers across hundreds of kilometres!', 'lecture_script': 'Details the role of fuels (petrol, diesel, LPG, coal) as chemical energy carriers, explaining the internal combustion engine process where burning fuel expands gases to turn wheels.', 'checkpoints': [{'question': 'What is the primary scientific function of a fuel such as petrol or LPG gas?', 'options': ['To release useful thermal and mechanical energy when combusted with oxygen', 'To freeze automobile engines in hot weather', 'To dissolve metal vehicle parts safely', 'To clean the car windshield while driving'], 'correct': 0, 'explanation': 'A fuel stores concentrated chemical energy that is released as intense heat and expanding gases during combustion with atmospheric oxygen.', 'study_insight': 'Fossil fuels like coal and petroleum originated from prehistoric plant and marine organism remains compressed underground under immense pressure for millions of years.'}, {'question': 'What happens inside an automobile engine cylinder to push the pistons and turn the wheels?', 'options': ['Air freezes into heavy ice blocks', 'Fuel ignites and burns rapidly, producing high-pressure hot expanding gas that pushes pistons', 'Magnets pull the wheels directly without any heat', 'Water turns into stone'], 'correct': 1, 'explanation': 'The rapid combustion of fuel produces intensely hot, expanding gases that drive the engine pistons down, converting thermal energy into mechanical rotation.', 'study_insight': 'Modern engines use electronic fuel injectors to vaporize fuel into ultra-fine droplets, ensuring complete combustion and maximizing mileage.'}]}, {'id': 7, 'title': 'Burning Diya', 'subtitle': 'Activity 4: Capillary Action, Fuel Vaporization & Steady Flame Chemistry', 'concept_html': '\n            <p>Every festival of lights brings an ancient scientific marvel to our doorsteps: the traditional earthen oil lamp, or <strong>diya</strong>. In <strong>Activity 4: Understanding Fuel in a Diya</strong>, students investigate what sustains a steady flame.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🪔 Capillary Liquid Siphon</span>\n                    <p class="text-xs text-slate-300">\n                        The twisted cotton wick rests inside the reservoir of mustard or sesame oil. Microscopic pores between cotton fibres act like tiny straw channels. Through <strong>capillary action</strong>, liquid oil defies gravity and creeps upward to the tip of the wick!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🔥 Continuous Vapor Combustion</span>\n                    <p class="text-xs text-slate-300">\n                        When lit, the heat of the flame vaporizes the ascending liquid oil into gas. It is actually the <em>oil vapor</em> reacting with surrounding oxygen that burns, not the cotton wick itself! The wick simply serves as the transport pipeline.\n                    </p>\n                </div>\n            </div>\n            <p>If the oil reservoir runs dry, the protective liquid shield vanishes and the dry cotton wick burns away in seconds, proving that the oil was the true fuel supplying energy to the flame!</p>\n        ', 'spoken_text': 'Examine Activity 4: The Science of a Burning Diya. During Diwali, we light beautiful clay lamps filled with mustard or sesame oil. But ask yourself: what is actually burning? It is not the cotton wick! The cotton wick is full of microscopic spaces between its twisted fibres. Through capillary action, liquid oil climbs steadily up the wick against gravity. At the burning tip, the high temperature vaporizes this liquid oil into gas. It is this hot oil vapor reacting with oxygen that burns with a warm golden flame! As long as oil flows up the wick, the flame glows brightly.', 'lecture_script': 'Covers Activity 4 on the burning diya, explaining capillary action drawing liquid oil up the cotton wick and oil vapor combustion with atmospheric oxygen.', 'checkpoints': [{'question': 'By what scientific physical process does liquid oil climb upward against gravity through a cotton diya wick?', 'options': ['Capillary action through microscopic spaces between cotton fibres', 'Magnetic attraction from the stars', 'Freezing into solid ice crystals', 'Solar reflection from the clay dish'], 'correct': 0, 'explanation': 'Capillary action occurs because intermolecular forces of adhesion between oil and cotton fibers overcome gravity, drawing liquid upward through narrow pores.', 'study_insight': 'The same capillary action helps tall redwood and banyan trees draw water from deep subterranean roots all the way up to leaves 50 metres high!'}, {'question': 'What happens when the oil reservoir in an earthen diya is completely exhausted?', 'options': ['The cotton wick burns away quickly and the flame extinguishes because oil was the real fuel', 'The diya starts producing electricity', 'The flame becomes ten times larger permanently', 'The clay bowl melts into water'], 'correct': 0, 'explanation': 'The oil is the actual chemical fuel sustaining combustion. Once oil runs out, the unprotected cotton fibers char and the flame goes out.', 'study_insight': 'A candle works on the exact same principle: melted paraffin wax is drawn up the central braided wick and vaporized to sustain the flame.'}]}, {'id': 8, 'title': 'Electric Current', 'subtitle': 'Flowing Electrons: Versatile Transformation into Motion, Heat & Light', 'concept_html': '\n            <p>Among all human discoveries, <strong>electricity</strong> is perhaps the most versatile and adaptable form of energy. Flowing through conductive copper wires, electric current powers our modern civilization.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">⚡ Flow of Electrons</span>\n                    <p class="text-xs text-slate-300">\n                        Electric current is the continuous directed flow of microscopic subatomic particles called <strong>electrons</strong> through a closed conductive loop (circuit). A power source (like a battery or generator) creates the electrical push (voltage).\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🔄 Universal Energy Chameleon</span>\n                    <p class="text-xs text-slate-300">\n                        Electricity effortlessly converts into any desired form: into <strong>movement</strong> via electric motors in fans and mixer-grinders, into <strong>heat</strong> via nichrome coils in toasters and geysers, into <strong>light</strong> via LEDs, and into <strong>sound</strong> via loudspeakers!\n                    </p>\n                </div>\n            </div>\n            <p>If any part of an electrical circuit is broken or switched off, electron flow ceases instantly, stopping all connected appliances.</p>\n        ', 'spoken_text': 'Consider the magic of electricity! At the flip of a tiny plastic wall switch, a dark room instantly floods with bright light, a refrigerator chills fresh milk, or a washing machine drum spins vigorously. Electricity is the rapid, organized drift of tiny charged particles called electrons moving through metal copper wires. Electricity is like an energy chameleon: connect it to a ceiling fan motor and it becomes kinetic rotation; connect it to an electric iron and it becomes soothing heat; connect it to a television and it becomes vibrant light and sound!', 'lecture_script': 'Explains electricity as the directed flow of electrons through conductive closed circuits, demonstrating its universal conversion into rotational motion, thermal heat, and light.', 'checkpoints': [{'question': 'What is an electric current fundamentally composed of in a copper wire circuit?', 'options': ['The directed flow of tiny charged subatomic particles called electrons', 'A stream of liquid water drops running inside metal pipes', 'Tiny magnetic marbles rolling along the outside of plastic cables', 'Compressed hot air expanding through glass tubes'], 'correct': 0, 'explanation': 'Electric current in metallic conductors consists of the collective drift of negatively charged valence electrons driven by electrical voltage.', 'study_insight': 'Copper and aluminum are excellent electrical conductors because their outer electrons are loosely bound and free to move from atom to atom.'}, {'question': 'Which household appliance converts electrical energy primarily into kinetic rotational motion?', 'options': ['A ceiling fan', 'An electric bread toaster', 'A room heating rod', 'A glowing torch bulb'], 'correct': 0, 'explanation': 'A ceiling fan uses an electromagnetic motor to convert incoming electrical energy into the mechanical rotational motion of its spinning blades.', 'study_insight': 'Electric motors utilize the interaction between magnetic fields and current-carrying wire coils to produce continuous torque and rotation.'}]}, {'id': 9, 'title': 'Efficient Lighting', 'subtitle': 'Energy Efficiency: Incandescent Filaments vs Solid-State LED Bulbs', 'concept_html': '\n            <p>Not all light fixtures are created equal. When electricity flows into a lighting device, we want it to produce bright <strong>light</strong>, not wasteful <strong>heat</strong>. This is the heart of <strong>energy efficiency</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">💡 Old Incandescent Filament Bulb</span>\n                    <p class="text-xs text-slate-300">\n                        Traditional yellow bulbs force electric current through a thin tungsten metal wire. The wire gets white-hot (over 2,500°C). Shockingly, <strong>90% of electricity is wasted as scorching heat</strong>, with only 10% emitted as useful visible light!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🌟 Modern Solid-State LED Bulb</span>\n                    <p class="text-xs text-slate-300">\n                        A Light Emitting Diode (LED) uses semiconductor microchips. Electrons release photons of light directly without needing to heat up a glowing wire. LEDs convert over <strong>80% of electricity directly into light</strong>, staying cool and using a fraction of the power!\n                    </p>\n                </div>\n            </div>\n            <p>A 9-watt modern LED bulb produces the exact same illumination as an old 60-watt filament bulb, conserving precious electricity and significantly lowering household electricity bills.</p>\n        ', 'spoken_text': 'Let us explore energy efficiency in modern lighting. For over a century, homes were illuminated by traditional glass bulbs with thin glowing tungsten filaments. But did you know that an old incandescent bulb wastes ninety percent of its electricity as scorching heat? You cannot even touch it after a few minutes! Today, India has revolutionized illumination with modern Light Emitting Diodes, or LEDs. LEDs use semiconductor chips that emit cool, brilliant light directly without wasting energy as heat. A tiny nine-watt LED produces the exact same brightness as an old sixty-watt bulb while using eighty-five percent less electrical energy!', 'lecture_script': 'Compares traditional incandescent filament bulbs with solid-state LED lighting, detailing the principles of energy efficiency, thermal energy waste, and electricity conservation.', 'checkpoints': [{'question': 'Why are modern LED bulbs considered far more energy-efficient than traditional tungsten filament bulbs?', 'options': ['They convert most electrical energy directly into light rather than wasting 90% as heat', 'They burn kerosene fuel secretly inside plastic', 'They only work when exposed to rain', 'They require three times more electricity to turn on'], 'correct': 0, 'explanation': 'LEDs produce cold light via semiconductor luminescence, converting over 80% of energy into light, whereas filament bulbs waste up to 90% as unwanted thermal heat.', 'study_insight': "India's national UJALA scheme distributed hundreds of millions of subsidized LED bulbs, saving gigawatts of electricity and reducing carbon dioxide emissions."}, {'question': 'If an old filament bulb consumes 60 watts of power to light a study desk, what wattage of modern LED can produce the same brightness?', 'options': ['About 7 to 9 watts', '150 watts', '600 watts', 'Zero watts because LEDs cannot light a desk'], 'correct': 0, 'explanation': 'Because LEDs have an exceptionally high luminous efficacy, a 7 to 9 watt LED matches the light output (lumens) of a 60 watt incandescent bulb.', 'study_insight': 'Wider adoption of energy-efficient appliances earned the BEE (Bureau of Energy Efficiency) 5-star rating saves national coal reserves and reduces household utility costs.'}]}, {'id': 10, 'title': 'Electric Safety', 'subtitle': 'Insulation, Water Hazards, Ceramic Fuses & Vital Life-Saving Precautions', 'concept_html': '\n            <p>Electricity is a fantastic servant, but it can be an unforgiving hazard if treated carelessly. The human body is composed of over 60% water containing dissolved mineral salts, making us <strong>conductors of electricity</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🚫 Wet Hands & Water Danger</span>\n                    <p class="text-xs text-slate-300">\n                        Pure water is a poor conductor, but moisture on human skin contains sweat and salts that drastically lower electrical skin resistance. <strong>Never touch any switch, plug, or wire with wet hands or while standing barefoot on a damp bathroom floor!</strong>\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🛡️ Insulation & Protective Fuses</span>\n                    <p class="text-xs text-slate-300">\n                        Copper wires are coated in flexible PVC plastic (an insulator that prevents electron leakage). Household distribution boxes feature safety <strong>fuses and Miniature Circuit Breakers (MCBs)</strong> that automatically trip and break the circuit during dangerous power surges!\n                    </p>\n                </div>\n            </div>\n            <p>Always insert safety plugs properly, never overload multi-plug sockets, and never poke metallic pencils, pins, or forks into wall sockets!</p>\n        ', 'spoken_text': 'Listen carefully to these vital rules of electrical safety! Because our human bodies are composed mostly of water with dissolved salts, our tissues conduct electric current very easily. If electric current passes through the body, it can cause severe burns, muscle spasms, or heart stoppage. Always remember: never, ever touch an electrical switch, socket, or wire with wet hands or while standing barefoot on wet ground! Water lowers skin resistance, allowing current to enter easily. Electrical wires are safely wrapped in colourful PVC plastic insulation. If you ever spot a frayed wire with exposed copper, alert an adult immediately and do not touch it!', 'lecture_script': 'Outlines electrical safety protocols, the human body as an electrolytic conductor, water hazard physics, plastic wire insulation, and circuit breaker/fuse protective mechanisms.', 'checkpoints': [{'question': 'Why is it extremely dangerous to operate an electric switch or plug with wet hands?', 'options': ['Water on the skin contains mineral salts that drastically reduce electrical resistance, risking severe electric shock', 'Water turns copper wires into rubber instantly', 'Wet fingers make the light bulb shine too brightly', 'Water makes plastic switches freeze'], 'correct': 0, 'explanation': 'Moisture containing dissolved salts provides a low-resistance conductive pathway, allowing potentially lethal electrical currents to flow into the body.', 'study_insight': 'Wearing rubber-soled slippers provides an insulating barrier that prevents electric current from finding an exit pathway to the ground.'}, {'question': 'What is the primary function of a safety fuse or Miniature Circuit Breaker (MCB) in a home electrical panel?', 'options': ['To generate extra electric current during power cuts', 'To automatically melt or trip, breaking the circuit whenever current exceeds safe limits', 'To play pleasant music when lights are turned on', 'To change the colour of the electricity'], 'correct': 1, 'explanation': 'A fuse contains a low-melting-point wire that safely melts during an overload, or an MCB trips open electromagnetically, interrupting the current before wires catch fire.', 'study_insight': 'Never replace a blown fuse wire with a thick iron nail or heavy copper cable; doing so disables the safety mechanism and can cause house fires.'}]}, {'id': 11, 'title': 'Clean Energy', 'subtitle': 'Fossil Fuel Emissions vs Zero-Pollution Sun, Wind & Water Energy', 'concept_html': '\n            <p>Most of the electricity powering our cities today is generated by burning pulverized <strong>coal</strong> inside massive thermal power plants. However, burning fossil fuels comes at a catastrophic environmental cost.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🏭 Coal Combustion & Smog</span>\n                    <p class="text-xs text-slate-300">\n                        Burning coal spews thick plumes of toxic smoke, fine particulate soot (PM2.5), sulfur dioxide, and greenhouse gases (carbon dioxide). These pollutants poison the air we breathe, cause respiratory illnesses like asthma, and accelerate global climate change.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🌿 Renewable Clean Energy</span>\n                    <p class="text-xs text-slate-300">\n                        In sharp contrast, the <strong>Sun</strong>, <strong>wind</strong>, and <strong>flowing water</strong> generate clean, green energy without emitting a single puff of smoke, soot, or toxic ash! Furthermore, unlike coal which will run out, sunlight and wind are inexhaustible.\n                    </p>\n                </div>\n            </div>\n            <p>Harnessing renewable energy is humanity\'s most crucial scientific mission to protect our blue planet and ensure fresh, clean air for future generations.</p>\n        ', 'spoken_text': 'Let us compare how our world produces electricity. In conventional thermal power plants, thousands of tonnes of black coal are burned every single hour. This combustion boils water into high-pressure steam, but it also releases massive clouds of suffocating black smoke, poisonous sulfur gases, and planet-warming carbon dioxide! This causes air pollution and smog. But nature offers us a far superior path: clean, renewable energy! Sunlight, blowing breezes, and gushing mountain rivers provide limitless power without creating any smoke, ash, or chemical waste. Clean energy keeps our skies crystal blue and our lungs healthy!', 'lecture_script': 'Contrasts the pollution, greenhouse emissions, and finite nature of coal-fired electricity with clean, infinite renewable energy harnessed from sunlight, wind, and water.', 'checkpoints': [{'question': 'What is the major environmental drawback of generating electricity by burning coal in thermal power plants?', 'options': ['It releases toxic smoke, soot, sulfur dioxide, and carbon dioxide that cause severe air pollution and global warming', 'It causes rivers to dry up instantly into ice', 'It makes the sky turn completely purple', 'It uses too much rubber'], 'correct': 0, 'explanation': 'Coal combustion produces vast quantities of greenhouse gases and particulate air pollutants that harm human respiratory health and heat the global atmosphere.', 'study_insight': "Coal is a non-renewable fossil fuel; once Earth's geological deposits are mined and burned, they cannot be replenished within human lifetimes."}, {'question': "Why are solar, wind, and hydroelectric energy classified as 'clean renewable energy'?", 'options': ['They generate electricity without producing smoke or toxic waste, and their natural sources never run out', 'They can only be used on completely silent days', 'They are made from melted plastic bottles', 'They only work when connected to car batteries'], 'correct': 0, 'explanation': 'Renewable energy sources naturally replenish themselves constantly without emitting harmful exhaust fumes or generating toxic combustion residues.', 'study_insight': "India possesses one of the world's largest solar installations, such as the Bhadla Solar Park in Rajasthan spanning over 5,700 hectares."}]}, {'id': 12, 'title': 'Wind Pinwheel', 'subtitle': 'Activity 6: Aerodynamic Pinwheels & Kinetic Wind Force in Action', 'concept_html': '\n            <p>Wind is simply air in motion. Though air is invisible, moving air possesses tremendous <strong>kinetic energy</strong>. In <strong>Activity 6: The Paper Pinwheel</strong>, students capture this invisible force.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🌀 Curved Vane Aerodynamics</span>\n                    <p class="text-xs text-slate-300">\n                        Cut a square sheet of craft paper diagonally from the four corners toward the centre. Fold every alternate corner flap to the central axis and secure with a smooth pushpin into a wooden pencil or stick.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">⚡ Kinetic Energy Transfer</span>\n                    <p class="text-xs text-slate-300">\n                        Blow a puff of breath or run forward holding the pinwheel into the breeze. The moving air molecules strike the cupped, angled paper blades, generating unequal aerodynamic pressure that spins the rotor into a dazzling visual blur!\n                    </p>\n                </div>\n            </div>\n            <p>Gigantic 100-metre industrial wind turbines across Tamil Nadu, Gujarat, and Rajasthan work on this exact same aerodynamic rotor principle, spinning generators to power entire cities!</p>\n        ', 'spoken_text': "Observe Activity 6: The Paper Pinwheel. Have you ever crafted a colourful paper pinwheel using origami paper and a simple pin attached to an eraser pencil? When the pinwheel sits motionless on a table, nothing happens. But the moment you blow a gentle puff of air or sprint across the school courtyard holding it, the paper blades spin vigorously! Invisible air molecules, rushing forward with kinetic energy, strike the angled curved blades. The air exerts mechanical pressure on the vanes, converting the wind's straight-line motion into continuous rotary spinning. This is precisely how modern wind turbines generate electricity!", 'lecture_script': 'Explains Activity 6 Paper Pinwheels, demonstrating how curved aerodynamic blades intercept horizontal wind kinetic energy and convert it into rotational mechanical motion.', 'checkpoints': [{'question': 'What causes the angled paper blades of a pinwheel to spin rapidly when you blow on them?', 'options': ['Moving air molecules possess kinetic energy that pushes against the curved blades, forcing them to rotate', 'The pushpin melts and pulls the paper', 'The paper becomes magnetic in moving air', 'The paper absorbs moisture and expands'], 'correct': 0, 'explanation': 'Kinetic energy from the moving air stream exerts mechanical pressure against the angled paper surfaces, translating linear wind force into rotational torque.', 'study_insight': "Wind energy is an indirect form of solar energy: the Sun heats the Earth's surface unevenly, creating atmospheric pressure differences that cause wind to blow."}, {'question': 'How do modern utility-scale wind turbine farms use this pinwheel principle to supply electricity to cities?', 'options': ['Giant aerodynamic blades spin in the wind, turning an internal shaft connected to an electric generator', 'The blades reflect sunlight onto rooftop water tanks', 'The blades chop incoming clouds into rain drops', 'The turbines burn firewood inside their towers'], 'correct': 0, 'explanation': 'Huge aerodynamic blades capture the kinetic force of the wind, rotating a central low-speed shaft linked through a gearbox to an electric generator producing alternating current.', 'study_insight': 'Modern wind turbine blades are constructed from lightweight glass-fiber reinforced polymer, shaped like aircraft wings to maximize aerodynamic lift.'}]}, {'id': 13, 'title': 'Sun Lens', 'subtitle': 'Activity 7: Optical Refraction & Concentrated Solar Radiant Energy', 'concept_html': '\n            <p>Sunlight illuminates our surroundings gently because its rays are dispersed evenly across the landscape. But what happens when you concentrate millions of dispersed light rays onto a single tiny point? <strong>Activity 7: The Magnifying Glass Experiment</strong> demonstrates this dramatically.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🔍 Convex Lens Refraction</span>\n                    <p class="text-xs text-slate-300">\n                        A magnifying glass features a double convex lens (thicker in the middle, thinner at edges). As parallel sunlight rays enter the curved glass, optical refraction bends (refracts) every ray toward a single central <strong>focal point</strong>.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🔥 Intense Thermal Concentration</span>\n                    <p class="text-xs text-slate-300">\n                        Holding the lens over a dry fallen leaf or dark paper focuses all radiant energy into a blindingly bright pinhead spot. Within seconds, temperatures at that focal point exceed 250°C! The dry leaf begins to char, smoulder, and emit curls of smoke!\n                    </p>\n                </div>\n            </div>\n            <p><strong>Safety Warning:</strong> Never look directly at the Sun through any lens, as concentrated rays will instantly cause permanent blindness. Always perform this experiment under adult supervision on a fire-safe stone surface.</p>\n        ', 'spoken_text': 'Now explore Activity 7: Focusing Sunlight with a Magnifying Glass. On a bright sunny morning, hold a curved convex magnifying glass over a piece of dry fallen leaf resting safely on a stone slab. Watch the circle of light shrink as you adjust the height, concentrating until it becomes a tiny, intensely bright golden dot! What is happening? The curved glass lens refracts and focuses hundreds of spread-out sunlight rays into a single microscopic point. All that radiant solar energy is concentrated into one spot, shooting the temperature above two hundred degrees Celsius! The leaf starts to smoulder and smoke! This proves the immense concentrated power of solar radiation.', 'lecture_script': 'Covers Activity 7 with the magnifying glass convex lens, explaining optical refraction focusing dispersed sunlight rays into an intense focal point that generates scorching heat.', 'checkpoints': [{'question': 'Why does a dry leaf begin to smoke when sunlight is focused onto it through a magnifying glass?', 'options': ['The curved convex lens concentrates many dispersed sunlight rays onto a single focal point, generating extreme thermal heat', 'The magnifying glass contains gunpowder inside its glass', 'The leaf is allergic to glass', 'The lens freezes the leaf until it shatters'], 'correct': 0, 'explanation': "Refraction through the convex lens gathers radiant energy spread across the lens surface and focuses it onto a tiny focal spot, raising the temperature above the leaf's combustion threshold.", 'study_insight': 'Concentrated Solar Power (CSP) plants use curved mirrors to focus sunlight onto central boiler towers, melting molten salt to drive steam turbines day and night!'}, {'question': 'What critical safety warning must always be observed when experimenting with magnifying lenses outdoors?', 'options': ['Never look directly at the Sun through any lens because concentrated rays can instantly destroy your eyesight', 'Never let the lens touch water', 'Only hold the lens upside down in the dark', 'Never allow shadows to touch the lens'], 'correct': 0, 'explanation': 'Focusing direct sunlight onto the sensitive retina at the back of the human eye will burn retinal cells within milliseconds, causing irreversible blindness.', 'study_insight': 'Solar cookers utilize this identical thermal concentration principle with shiny parabolic mirrors to boil lentils, rice, and bake bread without any gas or electricity.'}]}, {'id': 14, 'title': 'Water Wheel', 'subtitle': 'Activity 8: Hydro-Kinetic Power: Flowing Water Driving Rotational Work', 'concept_html': '\n            <p>Water may feel soft and soothing to the touch, but a rushing river or falling waterfall packs immense mechanical force. In <strong>Activity 8: The Homemade Water Wheel</strong>, students construct a working hydraulic turbine.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🥣 Spoons, Cups & Rotor Axis</span>\n                    <p class="text-xs text-slate-300">\n                        Insert 6 plastic spoons or small paper cups radially into a circular foam core or cork disc. Thread a smooth bamboo skewer or bicycle spoke through the centre as an axle, supported horizontally on two slotted cardboard pillars.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-blue-400 block mb-1">🌊 Gravitational Potential to Rotation</span>\n                    <p class="text-xs text-slate-300">\n                        Pour water steadily from a jug onto the curved cups. Water falling from a height possesses gravitational potential energy that converts into rushing kinetic energy. The impact force against each cup pushes it downward, creating rapid, unstoppable wheel rotation!\n                    </p>\n                </div>\n            </div>\n            <p>Tying a thread with a small paperclip to the spinning axle demonstrates mechanical work: the spinning water wheel easily hoists the weight upward against gravity!</p>\n        ', 'spoken_text': 'Observe Activity 8: The Homemade Water Wheel. Imagine crafting a wheel using a cork disc, six plastic spoons arranged like paddle blades, and a smooth wooden axle. Position your miniature water wheel beneath a steady stream of water poured from a jug. The instant water cascades down, the spoons catch the falling stream! The gravitational potential energy of the elevated water transforms into rushing kinetic energy, striking the spoon bowls with continuous impact force. The wheel spins vigorously on its axle! If you tie a thread with a tiny pebble to the axle, the rotating wheel hoists the pebble up into the air, proving that flowing water performs real mechanical work!', 'lecture_script': 'Explains Activity 8 Water Wheel construction, demonstrating how falling water converts gravitational potential energy into kinetic rotational force that performs useful mechanical work.', 'checkpoints': [{'question': 'What energy transformation occurs when water poured from a pitcher strikes the paddles of a water wheel?', 'options': ['Gravitational potential energy of falling water converts into mechanical kinetic energy of the spinning wheel', 'Water turns into chemical petroleum inside the spoons', 'The wheel turns into an ice cube', 'Light energy turns into nuclear radiation'], 'correct': 0, 'explanation': 'As water drops downward under gravity, its potential energy converts into kinetic energy. The momentum transferred upon striking the spoon paddles rotates the wheel.', 'study_insight': 'Hydropower stations store millions of tonnes of water behind high concrete dams; releasing this water through deep penstock pipes spins massive hydraulic turbines.'}, {'question': 'How did ancient civilizations use water wheels before electricity was ever discovered?', 'options': ['To grind wheat into flour, lift irrigation water into farm fields, and power blacksmith hammers', 'To charge electric mobile phones', 'To broadcast television signals across mountains', 'To fly aeroplanes across the sea'], 'correct': 0, 'explanation': 'Traditional water wheels provided direct mechanical shaft power for milling grains, driving irrigation water scoops (Norias), and powering sawmill blades.', 'study_insight': 'The Archimedes screw and the Persian wheel are related ancient hydraulic engineering marvels that utilized rotational water mechanics.'}]}, {'id': 15, 'title': 'Mountain Gharaats', 'subtitle': 'Traditional Himalayan Watermills: Zero-Carbon Engineering Heritage', 'concept_html': '\n            <p>Long before electrical grids reached remote mountain valleys, indigenous communities in Himachal Pradesh, Uttarakhand, and Jammu & Kashmir mastered zero-carbon water engineering through the <strong>Gharaat</strong> (traditional watermill).</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🏔️ Diverted Torrent & Wooden Chute</span>\n                    <p class="text-xs text-slate-300">\n                        Villagers construct a gentle stone-lined channel (kuhl) that diverts a portion of a raging glacier stream. The water is channeled into a steeply angled hollow wooden chute (penstock) carved from tree trunks, which shoots water at high velocity!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">⚙️ Heavy Stone Grinding Wheels</span>\n                    <p class="text-xs text-slate-300">\n                        The high-pressure jet hits a submerged multi-bladed wooden turbine wheel (panchakkari). An upright central spindle connects directly to a heavy circular grinding stone inside the upper room. As the stream flows, the stone rotates quietly, grinding whole wheat, maize, and millets into fresh nutritious flour!\n                    </p>\n                </div>\n            </div>\n            <p>Gharaats operate without a single drop of fuel or electricity, generating zero pollution. Furthermore, because stone grinding stays cool, heat-sensitive vitamins in the grain are preserved!</p>\n        ', 'spoken_text': 'Travel in your imagination to the snow-peaked mountains of Himachal Pradesh and Uttarakhand! Nestled beside foaming Himalayan mountain torrents stand small stone cottages called Gharaats. A Gharaat is an ingenious traditional watermill that has ground grain for over a thousand years without using a single watt of electricity or a single drop of petrol! Fast-flowing mountain water is diverted down a steep wooden flume. The high-speed water jet strikes angled wooden turbine blades underneath the floor, spinning an upright axle. Upstairs, a heavy circular grinding stone rotates smoothly over another, grinding wheat and corn into wholesome flour. It is a masterclass in clean, traditional engineering!', 'lecture_script': 'Details the traditional Himalayan Gharaat (watermill), explaining the diversion canal, wooden chute, horizontal turbine runner, and upper grinding stones operating purely on hydraulic stream power.', 'checkpoints': [{'question': "What powers a traditional Himalayan 'Gharaat' to grind grain into flour without electricity?", 'options': ['The kinetic force of fast-flowing mountain stream water striking wooden turbine blades', 'A hidden underground diesel generator', 'Solar electric batteries charged during the night', 'Trained horses walking in continuous circles'], 'correct': 0, 'explanation': 'A Gharaat harnesses the natural kinetic and potential energy of high-altitude mountain torrents directed through a wooden chute onto a submerged runner turbine.', 'study_insight': 'Slow cold-stone milling in a Gharaat keeps flour temperatures low, preserving healthy wheat-germ oils, bran fibre, and B-complex vitamins.'}, {'question': 'Why are indigenous traditional technologies like the Gharaat being revived and modernized today?', 'options': ['Because they provide 100% clean, renewable, decentralized local energy with zero carbon footprint', 'Because they produce heavy black smoke', 'Because they consume high-voltage electricity', 'Because they make grain turn into plastic'], 'correct': 0, 'explanation': 'Modernizing Gharaat turbines with precision ball bearings and micro-generators allows mountain villages to mill grain and generate local electricity sustainably.', 'study_insight': 'Decentralized micro-hydro installations based on modernized Gharaats provide self-reliant energy security to isolated Himalayan border communities.'}]}, {'id': 16, 'title': 'Green Future', 'subtitle': 'Modern Renewable Infrastructure & Responsible Energy Conservation Habits', 'concept_html': '\n            <p>Our global transition from polluting fossil fuels to clean renewable energy requires both <strong>grand national infrastructure</strong> and <strong>mindful individual habits</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">☀️ Mega Solar Parks & Wind Farms</span>\n                    <p class="text-xs text-slate-300">\n                        Across sun-drenched plains and windy coastlines, thousands of photovoltaic solar panels and tall aerodynamic wind turbines generate clean electricity directly feeding into India\'s National Power Grid, powering trains, schools, and hospitals.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🌱 Everyday Conservation Habits</span>\n                    <p class="text-xs text-slate-300">\n                        Remember the golden scientific rule: <em>The cleanest energy is the energy we never waste!</em> Simple daily actions preserve our planet:\n                        <ul class="list-disc pl-4 mt-1 text-[11px] space-y-1">\n                            <li>Switch off fans, lights, and monitors when stepping out of a room.</li>\n                            <li>Unplug chargers when devices reach 100% to stop phantom power draw.</li>\n                            <li>Walk, cycle, or use school buses instead of individual petrol cars.</li>\n                            <li>Dry washed clothes in warm natural sunshine rather than electric dryers.</li>\n                        </ul>\n                    </p>\n                </div>\n            </div>\n            <p>Every student is an active Earth Guardian: through conscious energy conservation, we safeguard our atmosphere and preserve Earth\'s climate for all living beings!</p>\n        ', 'spoken_text': 'We conclude our exploration of energy with a shared pledge for a green future! Across our nation, magnificent modern infrastructure is rising: vast solar photovoltaic parks in our deserts, towering wind turbines along ocean coasts, and smart electrical grids. But large solar parks alone cannot save our planet; our personal habits matter just as much! Remember that the cleanest kilowatt of energy is the one you never waste. Always switch off fans, computers, and lights when leaving an empty room. Walk or ride a bicycle for short errands. By choosing clean renewable energy and cutting wasteful consumption, every young scientist helps protect our precious planet Earth!', 'lecture_script': 'Synthesizes modern renewable energy infrastructure (solar parks, wind farms, hydro grids) with personal energy conservation practices and environmental stewardship.', 'checkpoints': [{'question': 'Which of the following actions is the most effective daily habit for conserving electrical energy at home?', 'options': ['Switching off fans, air conditioners, and lights immediately upon exiting an empty room', 'Leaving the television running while sleeping to keep the room cheerful', 'Keeping the refrigerator door wide open while studying', 'Charging a smartphone continuously for three days straight'], 'correct': 0, 'explanation': 'Turning off appliances when not in use stops unnecessary electricity consumption, reducing the amount of coal burned at power stations.', 'study_insight': "'Phantom loads' or vampire draw refers to the electricity consumed by appliances (televisions, microwave displays, chargers) even when placed in standby mode."}, {'question': "What core message does the scientific principle 'The cleanest energy is the energy saved' teach us?", 'options': ['Preventing wasteful energy consumption eliminates the pollution and resource depletion needed to generate it in the first place', 'That we should never use any electricity ever again', 'That burning coal produces cleaner air than solar panels', 'That energy can only be saved inside glass jars'], 'correct': 0, 'explanation': 'Energy conservation directly reduces demand on power generating stations, preventing greenhouse gas emissions, saving water, and cutting fossil fuel extraction.', 'study_insight': "Replacing ordinary household appliances with BEE 5-star rated equipment can cut a family's electricity consumption by up to 30% annually."}]}]

QUIZ_QUESTIONS = [{'id': 1, 'question': 'In science, what is energy defined as?', 'options': ['A material solid that takes up space and has mass', 'The ability or capacity to do work, cause motion, produce heat, light, and sound', 'A magnetic liquid found only in car batteries', 'A chemical element found only in diamonds'], 'answer': 1, 'explanation': 'Energy is scientifically defined as the ability or capacity to perform work, create motion, or produce light, sound, and thermal changes.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Fundamental Definition of Energy:</strong></p>\n                <p class='text-slate-300'>Energy is not matter; it has no mass and occupies no volume. Rather, it is an intrinsic property of physical systems that enables them to exert forces, perform mechanical work, radiate waves, or transfer heat.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (The ability or capacity to do work)</p>\n            </div>\n        "}, {'id': 2, 'question': 'What kind of energy does a stretched rubber balloon contain before its nozzle is released?', 'options': ['Nuclear atomic energy', 'Elastic potential energy stored in its stretched skin and compressed air', 'Electrical current energy', 'Magnetic rotational energy'], 'answer': 1, 'explanation': 'Inflating the balloon stretches its rubber polymer chains and compresses air molecules inside, storing elastic potential energy.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Elastic Potential Energy:</strong></p>\n                <p class='text-slate-300'>Potential energy is stored energy resulting from deformation or relative position. When rubber is stretched, molecular bonds act like miniature coiled springs storing mechanical potential energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Elastic potential energy)</p>\n            </div>\n        "}, {'id': 3, 'question': "According to Newton's law of motion, why does a balloon rocket accelerate forward along a guide string?", 'options': ['Because the rapid backward ejection of compressed air produces an equal and opposite forward thrust', 'Because the string magnetically pulls the straw forward', 'Because the air inside turns into hot steam', 'Because room air pulls the balloon from the front'], 'answer': 0, 'explanation': 'For every action, there is an equal and opposite reaction. The backward jet of escaping air produces forward reaction thrust on the balloon.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Action-Reaction Rocket Thrust:</strong></p>\n                <p class='text-slate-300'>As air rushes out backward (Action), it imparts an equal forward momentum to the balloon-straw assembly (Reaction), pushing it along the guide string.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Equal and opposite forward thrust)</p>\n            </div>\n        "}, {'id': 4, 'question': 'What physical phenomenon is essential for any musical instrument or rubber band to generate sound?', 'options': ['Rapid back-and-forth mechanical vibrations', 'Melting into a liquid puddle', 'Complete chemical combustion with fire', 'Cooling down to absolute zero'], 'answer': 0, 'explanation': 'All sound originates from physical vibrations. Vibrating objects disturb surrounding air particles, creating compression waves.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Sound Generation & Acoustic Waves:</strong></p>\n                <p class='text-slate-300'>When a string oscillates, it pushes against air molecules. These colliding molecules propagate outward as alternating longitudinal compressions and rarefactions, detected by our ears as sound.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Rapid back-and-forth mechanical vibrations)</p>\n            </div>\n        "}, {'id': 5, 'question': 'How does stretching a rubber band tighter across a shoebox change the sound pitch it produces when plucked?', 'options': ['The pitch becomes higher because the band vibrates at a higher frequency', 'The pitch becomes much deeper like thunder', 'The sound disappears and turns into electricity', 'The pitch remains completely unchanged'], 'answer': 0, 'explanation': 'Higher tension increases the restoring force of the rubber band, causing it to oscillate more cycles per second (higher frequency/pitch).', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Tension and Acoustic Frequency:</strong></p>\n                <p class='text-slate-300'>Frequency (f) is directly proportional to the square root of tension. Greater tension = faster oscillations = higher frequency = higher perceived pitch.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Pitch becomes higher)</p>\n            </div>\n        "}, {'id': 6, 'question': 'What is the role of the hollow cardboard shoebox in the rubber band guitar experiment?', 'options': ['It acts as a resonance chamber that amplifies the vibrating sound waves', 'It absorbs all sound so nobody can hear it', 'It generates electricity to power a speaker', 'It prevents the rubber band from stretching'], 'answer': 0, 'explanation': 'The hollow box vibrates sympathetically with the plucked rubber band, forcing a larger volume of enclosed air to oscillate and amplifying the volume.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Resonance and Acoustic Amplification:</strong></p>\n                <p class='text-slate-300'>The wooden body of an acoustic guitar, sitar, or cardboard shoebox provides a large surface area that couples vibrational energy efficiently into surrounding air.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Resonance chamber that amplifies sound)</p>\n            </div>\n        "}, {'id': 7, 'question': 'What happens at the molecular level when a bowl of water absorbs radiant solar energy on a sunny terrace?', 'options': ['Water molecules absorb radiant energy and jiggle faster, raising the water temperature', 'Water molecules stop moving and freeze into ice', 'Water splits into solid gold bars', 'Water molecules lose all mass'], 'answer': 0, 'explanation': 'Radiant solar photons excite the kinetic motion of water molecules, increasing the average internal kinetic energy (temperature).', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Thermal Physics of Solar Absorption:</strong></p>\n                <p class='text-slate-300'>Temperature is the direct microscopic measure of molecular kinetic energy. Absorbing electromagnetic radiation converts radiant energy into thermal molecular vibration.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Molecules jiggle faster, raising temperature)</p>\n            </div>\n        "}, {'id': 8, 'question': 'Why does black-painted metal absorb radiant solar heat significantly faster than polished white metal?', 'options': ['Black surfaces absorb nearly all incoming solar wavelengths rather than reflecting them', 'Black paint contains tiny electric batteries', 'Black metal is much lighter in weight', 'White paint absorbs radio waves'], 'answer': 0, 'explanation': 'Dark, non-reflective surfaces absorb nearly 95% of incident electromagnetic radiation, whereas white surfaces reflect most visible light back into space.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Albedo and Radiant Absorption:</strong></p>\n                <p class='text-slate-300'>White objects have high albedo (reflectance); black objects have low albedo and high emissivity, maximizing solar thermal conversion.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Black surfaces absorb nearly all incoming solar wavelengths)</p>\n            </div>\n        "}, {'id': 9, 'question': 'What fundamental law of physics states that energy can neither be created nor destroyed, only transformed?', 'options': ['The Law of Conservation of Energy', 'The Law of Magnetic Gravity', 'The Law of Floating Objects', 'The Law of Sound Speed'], 'answer': 0, 'explanation': 'The First Law of Thermodynamics (Law of Conservation of Energy) establishes that the total energy of an isolated system remains constant.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Law of Conservation of Energy:</strong></p>\n                <p class='text-slate-300'>Energy can change forms (e.g. chemical to mechanical, electrical to light), but the total amount of energy in the universe is immutable.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The Law of Conservation of Energy)</p>\n            </div>\n        "}, {'id': 10, 'question': 'Which of the following is an example of kinetic energy in daily life?', 'options': ['A fast-flowing mountain river carrying pebbles downstream', 'A rock resting motionless on top of a hill', 'A charged battery kept inside a drawer', 'A lump of coal stored in a sack'], 'answer': 0, 'explanation': 'Kinetic energy is the energy possessed by an object due to its motion. A flowing river is in active motion, possessing kinetic energy.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Kinetic Energy vs Potential Energy:</strong></p>\n                <p class='text-slate-300'>Kinetic energy is energy of motion (E = 0.5 * m * v²). Moving water, flying birds, and rolling balls possess kinetic energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (A fast-flowing mountain river)</p>\n            </div>\n        "}, {'id': 11, 'question': 'What primary form of energy is stored inside food items like rotis, rice, dal, and bananas?', 'options': ['Chemical potential energy', 'High-voltage electrical energy', 'Nuclear radioactive energy', 'Magnetic rotational energy'], 'answer': 0, 'explanation': 'Food stores chemical potential energy within the chemical bonds of glucose, starches, fats, and proteins synthesized by plants.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Chemical Energy in Biological Nutrition:</strong></p>\n                <p class='text-slate-300'>Photosynthesis converts radiant solar energy into chemical bond energy in carbohydrates (C6H12O6), which cellular respiration unlocks.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Chemical potential energy)</p>\n            </div>\n        "}, {'id': 12, 'question': 'How does the human body function like a rechargeable battery regarding energy storage?', 'options': ['It stores surplus energy from food as glycogen in the liver/muscles and fat tissue to supply steady energy later', 'It must be plugged into a 220V wall socket overnight', 'It runs on liquid petrol poured into the ears', 'It has positive and negative copper terminals on the hands'], 'answer': 0, 'explanation': 'The human body stores excess dietary glucose as glycogen in liver and muscle cells, and lipids in adipose tissue, releasing it during fasting or exertion.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Biological Glycogen & Fat Storage:</strong></p>\n                <p class='text-slate-300'>When blood glucose rises, insulin stimulates glycogen synthesis. Between meals, glucagon converts glycogen back to glucose, sustaining energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Stores surplus energy from food as glycogen and fat)</p>\n            </div>\n        "}, {'id': 13, 'question': "What is the primary definition of a 'fuel' in science and engineering?", 'options': ['Any substance that releases useful thermal energy when burned with oxygen', 'Any liquid that freezes below zero degrees', 'A metal that conducts electricity without resistance', 'A type of rock that repels water'], 'answer': 0, 'explanation': 'A fuel is a combustible substance containing concentrated chemical energy that produces heat and expanding gases upon oxidation.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Combustion Chemistry of Fuels:</strong></p>\n                <p class='text-slate-300'>Fuel + Oxygen -> Carbon Dioxide + Water + Intense Heat (Thermal Energy). This released heat powers engines, turbines, and cooking stoves.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Releases useful thermal energy when burned with oxygen)</p>\n            </div>\n        "}, {'id': 14, 'question': 'What fossil fuel is stored under high pressure in red domestic kitchen cylinders across India?', 'options': ['LPG (Liquefied Petroleum Gas)', 'Liquid Nitrogen', 'Solid Coal Dust', 'Uranium Oxide'], 'answer': 0, 'explanation': 'LPG, primarily consisting of propane and butane compressed into a liquid state, powers domestic kitchen gas burners cleanly and instantly.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Domestic LPG Gas:</strong></p>\n                <p class='text-slate-300'>LPG burns with a hot, soot-free blue flame when mixed with appropriate oxygen, producing far less indoor smoke than traditional firewood or dung cakes.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (LPG - Liquefied Petroleum Gas)</p>\n            </div>\n        "}, {'id': 15, 'question': 'How does an internal combustion engine inside a bus convert chemical fuel into wheel rotation?', 'options': ['Burning fuel produces hot expanding gases that push metal pistons downward, turning the crankshaft and wheels', 'Fuel dissolves the rubber tires so they roll faster', 'Fuel turns into steam that pulls the vehicle magnetically', 'The engine freezes the fuel into solid carbon gears'], 'answer': 0, 'explanation': 'The rapid expansion of hot combustion gases in the engine cylinder forces the piston down, converting linear thrust into rotary motion.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Internal Combustion Cycle:</strong></p>\n                <p class='text-slate-300'>Intake -> Compression -> Power (Ignition & Expansion pushing Piston) -> Exhaust. The mechanical connecting rod converts reciprocating piston motion into continuous shaft rotation.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Burning fuel produces hot expanding gases pushing pistons)</p>\n            </div>\n        "}, {'id': 16, 'question': 'By what scientific mechanism does oil climb from the clay reservoir up to the tip of a cotton diya wick?', 'options': ['Capillary action through microscopic spaces between twisted cotton fibres', 'Gravitational pull from the moon', 'Electrical conduction along copper threads', 'Evaporation into the clouds'], 'answer': 0, 'explanation': 'Capillary action draws liquid oil upward against gravity due to adhesive forces between oil molecules and cellulose fibers.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Capillary Action in Wicks:</strong></p>\n                <p class='text-slate-300'>Narrow pores between cotton fibres create high surface tension capillary forces that draw liquid oil upward, maintaining a continuous fuel feed.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Capillary action through microscopic spaces)</p>\n            </div>\n        "}, {'id': 17, 'question': 'In a burning diya or candle, what is actually burning to produce the luminous golden flame?', 'options': ['Hot oil or wax vapor reacting with oxygen at the tip', 'The solid cotton thread itself', 'The earthen clay bowl', 'The nitrogen gas in the room'], 'answer': 0, 'explanation': "The flame's heat vaporizes ascending liquid oil into hydrocarbon gas, which mixes with ambient oxygen and combusts with a bright flame.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Vapor Phase Combustion:</strong></p>\n                <p class='text-slate-300'>Liquids and solids do not burn directly; they must first be volatilized into vapor. The cotton wick merely acts as a transport siphon and support structure.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Hot oil or wax vapor reacting with oxygen)</p>\n            </div>\n        "}, {'id': 18, 'question': 'What is an electric current fundamentally composed of in a conductive circuit?', 'options': ['The organized drift of negatively charged electrons through a conductor', 'A stream of microscopic water droplets flowing inside cables', 'A beam of radio waves traveling through the air', 'Compressed air expanding inside copper tubes'], 'answer': 0, 'explanation': 'Electric current is the continuous movement of free conduction electrons propelled through metallic crystal lattices by an electric potential gradient.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Nature of Electric Current:</strong></p>\n                <p class='text-slate-300'>Metals like copper possess a 'sea' of delocalized valence electrons. When a voltage is applied, electrons drift in unison, transferring electrical energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Organized drift of negatively charged electrons)</p>\n            </div>\n        "}, {'id': 19, 'question': 'Which of the following household appliances converts electrical energy primarily into thermal heat?', 'options': ['An electric clothes iron and room heater', 'A ceiling fan', 'A radio loudspeaker', 'A battery torch'], 'answer': 0, 'explanation': 'An electric iron contains high-resistance nichrome heating elements that convert electrical current into intense thermal heat via Joule heating.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Joule Heating Effect:</strong></p>\n                <p class='text-slate-300'>When electric current encounters resistance in a heating element (H = I² * R * t), electrical potential energy transforms into thermal energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (An electric clothes iron and room heater)</p>\n            </div>\n        "}, {'id': 20, 'question': 'What happens immediately when an electrical switch is turned off in a home circuit?', 'options': ['The circuit is broken open, stopping the flow of electrons instantly', 'Electricity spills out of the wire onto the floor', 'The appliance turns into a gas', 'The voltage increases ten times'], 'answer': 0, 'explanation': 'Opening a switch creates an air gap in the circuit; because air is a powerful insulator, the electron loop is interrupted and current stops immediately.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Open Circuit vs Closed Circuit:</strong></p>\n                <p class='text-slate-300'>Electrons can only flow through an unbroken, continuous conductive loop. An open switch breaks the continuity, terminating power delivery.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The circuit is broken open, stopping flow of electrons)</p>\n            </div>\n        "}, {'id': 21, 'question': 'Why does an old incandescent filament bulb become extremely hot to the touch after just a few minutes?', 'options': ['Because nearly 90% of the electrical energy is wasted as heat, with only 10% emitted as light', 'Because the glass reacts chemically with air', 'Because the light bulb produces nuclear fire', 'Because the wire absorbs cold from the room'], 'answer': 0, 'explanation': 'Tungsten filaments require extreme temperatures (>2,500°C) to glow (incandesce), wasting approximately 90% of incoming electricity as infrared heat.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Incandescence Inefficiency:</strong></p>\n                <p class='text-slate-300'>Incandescent bulbs produce light as an incidental byproduct of extreme thermal heating, making them notoriously inefficient energy converters.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Nearly 90% of electricity is wasted as heat)</p>\n            </div>\n        "}, {'id': 22, 'question': 'How do modern solid-state LED bulbs generate bright light so efficiently without getting burning hot?', 'options': ['Semiconductor chips release light photons directly through electronic electroluminescence', 'They burn tiny drops of oil inside sealed glass', 'They reflect sunlight stored from daytime', 'They use miniature nuclear batteries'], 'answer': 0, 'explanation': 'LEDs produce cold light via semiconductor recombination, converting over 80% of electrical energy directly into visible light photons.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Electroluminescence in LEDs:</strong></p>\n                <p class='text-slate-300'>In a p-n junction diode, electrons drop across the bandgap, shedding excess energy directly as light photons rather than random thermal vibrations.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Semiconductor chips release light photons directly)</p>\n            </div>\n        "}, {'id': 23, 'question': 'Why does moisture or wet skin make handling electrical switches especially dangerous?', 'options': ['Water containing dissolved salts drastically lowers skin electrical resistance, allowing lethal current to enter the body', 'Water makes switches explode into dust', 'Wet fingers attract lightning bolts from the clouds', 'Water turns plastic switches into iron'], 'answer': 0, 'explanation': 'Dry human skin has high electrical resistance (~100,000 ohms), but wet skin with perspiration salts drops to below 1,000 ohms, permitting dangerous current flow.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Ohm's Law & Human Skin Resistance:</strong></p>\n                <p class='text-slate-300'>Current I = V / R. When skin resistance (R) drops due to water and sweat, a standard 230V household supply can deliver lethal shocks (>50 mA).</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Water with salts drastically lowers skin resistance)</p>\n            </div>\n        "}, {'id': 24, 'question': 'What material is coated over copper electrical wires to prevent shocks and short circuits?', 'options': ['Flexible PVC plastic, which acts as a strong electrical insulator', 'Aluminium foil, which attracts electrons', 'Wet cotton string', 'Saltwater jelly'], 'answer': 0, 'explanation': 'Polyvinyl chloride (PVC) plastic has tightly bound valence electrons that do not permit current flow, making it an ideal protective insulator.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Conductors vs Insulators:</strong></p>\n                <p class='text-slate-300'>Copper cores provide low-resistance pathways for current, while exterior PVC insulation confines electrons safely within the circuit.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Flexible PVC plastic as an electrical insulator)</p>\n            </div>\n        "}, {'id': 25, 'question': 'What does a Miniature Circuit Breaker (MCB) do during an accidental overload or short circuit?', 'options': ['It automatically trips and opens the circuit, halting dangerous current flow before a fire starts', 'It blows air to cool down the house', 'It doubles the electricity to overcome the problem', 'It rings an alarm and plays recorded music'], 'answer': 0, 'explanation': 'MCBs utilize thermal bimetallic strips and electromagnetic coils to automatically trip open within milliseconds when current exceeds safe operating thresholds.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Modern Circuit Breaker Protection:</strong></p>\n                <p class='text-slate-300'>MCBs replaced old sacrificial fuse wires because they can be easily reset with a toggle switch once the electrical fault is cleared.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Automatically trips and opens the circuit)</p>\n            </div>\n        "}, {'id': 26, 'question': 'What toxic environmental emissions are released when coal is burned in thermal power stations?', 'options': ['Soot (PM2.5), sulfur dioxide, nitrogen oxides, and greenhouse carbon dioxide', 'Clean pure oxygen gas', 'Fresh drinking water drops', 'Fragrant flower perfume'], 'answer': 0, 'explanation': 'Burning coal releases heavy greenhouse gases, acid-rain causing sulfur oxides, and particulate matter that trigger severe lung and heart illnesses.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Thermal Power Environmental Impact:</strong></p>\n                <p class='text-slate-300'>Coal combustion produces ash slurry containing toxic heavy metals (mercury, arsenic, lead) and massive greenhouse emissions driving global warming.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Soot, sulfur dioxide, nitrogen oxides, and carbon dioxide)</p>\n            </div>\n        "}, {'id': 27, 'question': "Why are solar, wind, and water energy called 'renewable' sources of energy?", 'options': ['Because natural planetary processes constantly replenish them and they will never run out', 'Because they must be replaced by new machines every week', 'Because they are made from recycled plastic bags', 'Because they can only be used during rainy seasons'], 'answer': 0, 'explanation': 'Unlike finite fossil fuels that take millions of years to form, solar radiation, atmospheric winds, and hydrological river cycles replenish perpetually.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Renewable Energy Sustainability:</strong></p>\n                <p class='text-slate-300'>The Sun will radiate energy for another 5 billion years; its thermal gradient drives winds and rain cycles continuously without depleting resource stocks.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Naturally replenished and will never run out)</p>\n            </div>\n        "}, {'id': 28, 'question': 'In the paper pinwheel experiment (Activity 6), what forces the curved blades to spin?', 'options': ['Moving air molecules transferring their kinetic energy and exerting pressure against the angled blades', 'Static electricity in the pushpin', 'Thermal heat melting the paper', 'Magnetic fields from the wooden pencil'], 'answer': 0, 'explanation': 'Air in motion possesses kinetic energy. As moving air strikes the angled paper flaps, an aerodynamic pressure differential generates rotational torque.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Aerodynamics of Pinwheel Rotors:</strong></p>\n                <p class='text-slate-300'>The cupped geometry creates high pressure on the concave face and lower pressure behind it, producing unbalanced forces that spin the rotor.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Moving air molecules transferring kinetic energy)</p>\n            </div>\n        "}, {'id': 29, 'question': 'What is the ultimate origin of all wind on planet Earth?', 'options': ["The Sun heating the Earth's surface and atmosphere unevenly", 'Ocean waves pushing air from underneath', 'Trees waving their branches simultaneously', 'Automobiles driving on highways'], 'answer': 0, 'explanation': 'The equator receives more direct solar radiation than the poles, creating atmospheric temperature and pressure differences that drive global wind circulation.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Solar Origin of Wind Energy:</strong></p>\n                <p class='text-slate-300'>Warm air at the equator expands and rises, creating low pressure. Cooler, denser polar air flows in to replace it, creating perpetual planetary wind currents.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The Sun heating the Earth's surface unevenly)</p>\n            </div>\n        "}, {'id': 30, 'question': 'How do modern utility wind turbines generate electricity from passing coastal breezes?', 'options': ['Aerodynamic rotor blades rotate a central shaft connected to an electromagnetic generator', 'They capture wind in plastic sacks to burn later', 'They bounce sunlight onto electric solar panels', 'They use wind to pump diesel fuel into trucks'], 'answer': 0, 'explanation': 'Aerodynamic lift spins the rotor blades (10-20 rpm), which a gearbox speeds up to ~1,500 rpm to drive an induction generator producing electricity.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Wind Turbine Electromechanics:</strong></p>\n                <p class='text-slate-300'>Wind Kinetic Energy -> Rotor Shaft Mechanical Energy -> Generator Electromagnetic Energy -> High Voltage Grid AC Current.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Rotor blades rotate a shaft connected to an electric generator)</p>\n            </div>\n        "}, {'id': 31, 'question': 'In Activity 7, what optical phenomenon allows a magnifying glass to focus scattered sunlight onto a single hot spot?', 'options': ['Refraction (bending) of light rays passing through a curved convex glass lens', 'Reflection from a flat mirror surface', 'Complete absorption of all light into the glass', 'Diffraction through a razor blade'], 'answer': 0, 'explanation': 'A convex lens is thicker in the center, causing parallel light rays to refract (bend inward) toward a single concentrated focal point.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Convex Lens Refraction & Focal Point:</strong></p>\n                <p class='text-slate-300'>Light travels slower in glass than in air. The curved glass curvature slows the perimeter of the light wave differently, bending all rays into focus.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Refraction of light rays through a convex lens)</p>\n            </div>\n        "}, {'id': 32, 'question': 'What practical clean cooking technology utilizes concentrated solar radiation without gas or electricity?', 'options': ['A parabolic solar cooker', 'A kerosene pressure stove', 'A diesel camping burner', 'A coal-fired tandoor'], 'answer': 0, 'explanation': 'Solar cookers use shiny curved parabolic reflectors or insulated glass boxes to concentrate sunlight, heating cooking pots to over 150°C.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Solar Thermal Cooking:</strong></p>\n                <p class='text-slate-300'>Curved mirrors focus sunlight rays onto a black cooking pot, cooking rice, dal, and vegetables purely through free, zero-pollution solar thermal energy.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (A parabolic solar cooker)</p>\n            </div>\n        "}, {'id': 33, 'question': 'In the homemade water wheel experiment (Activity 8), what enables falling water to lift a suspended weight?', 'options': ['Falling water transfers its kinetic energy to the paddles, producing axle rotation that winds up the thread', 'Water turns the string into an electric wire', 'The weight floats upward because it smells the water', 'The cardboard pillar pulls the string magnetically'], 'answer': 0, 'explanation': 'Falling water transfers momentum to the cups, turning the axle. The rotating axle provides mechanical shaft work that reels up the suspended weight.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Mechanical Work from Hydraulic Energy:</strong></p>\n                <p class='text-slate-300'>Work = Force * Distance. The gravitational potential energy of falling water translates into torque, lifting the load against gravity.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Falling water transfers kinetic energy to paddles, producing rotation)</p>\n            </div>\n        "}, {'id': 34, 'question': "What is a traditional Himalayan 'Gharaat'?", 'options': ['An indigenous watermill powered by diverted mountain streams to grind grain into flour without electricity', 'A diesel-powered tractor used on snow slopes', 'A stone bridge built across dry rivers', 'A wooden boat used for ocean fishing'], 'answer': 0, 'explanation': 'A Gharaat is an ancient Himalayan hydraulic watermill where rushing glacier torrents strike wooden turbine blades to spin heavy stone grain mills.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Himalayan Gharaat Heritage:</strong></p>\n                <p class='text-slate-300'>Gharaats have operated across the Himalayas for centuries, grinding wheat, corn, and barley cleanly with zero fossil fuels or greenhouse emissions.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Indigenous watermill powered by mountain streams)</p>\n            </div>\n        "}, {'id': 35, 'question': 'Why does stone-milled flour from a traditional Gharaat have superior nutritional value compared to fast industrial electric mills?', 'options': ['Cold stone grinding keeps temperatures low, preserving sensitive vitamins and natural wheat-germ oils', 'The stone injects chemical preservatives into the flour', 'The water adds sugar to the grain', 'The stone bleaches the wheat white'], 'answer': 0, 'explanation': 'High-speed electric roller mills generate friction heat exceeding 90°C that degrades wheat-germ oils and vitamins. Cool Gharaat stone milling preserves nutrients.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Nutritional Benefits of Cold Milling:</strong></p>\n                <p class='text-slate-300'>Gharaat milling preserves heat-sensitive vitamins (thiamine, vitamin E) and prevents the oxidation of essential fatty acids present in the grain germ.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Cold stone grinding preserves vitamins and wheat-germ oils)</p>\n            </div>\n        "}, {'id': 36, 'question': 'How did ancient merchant ships cross vast oceans before the invention of steam and diesel engines?', 'options': ['They hoisted large fabric sails that captured the kinetic energy of trade winds to push the ship forward', 'They plugged extension cords into coastal lighthouses', 'They used giant underwater electric propellers', 'They waited for ocean water to flow downhill'], 'answer': 0, 'explanation': 'Sailing ships utilized expansive canvas sails to harness the aerodynamic thrust of prevailing ocean trade winds, navigating thousands of nautical miles.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Historical Wind Navigation:</strong></p>\n                <p class='text-slate-300'>Indian maritime trade across the Arabian Sea and Bay of Bengal relied on seasonal monsoon winds to propel wooden dhows and sailing craft.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Hoisting large fabric sails to capture kinetic wind energy)</p>\n            </div>\n        "}, {'id': 37, 'question': "What is 'phantom power draw' (or vampire power) in domestic household electricity?", 'options': ['Electricity continuously consumed by electronic appliances left in standby mode or plugged-in chargers', 'Electricity stolen by ghosts in old houses', 'Power generated by lightning striking rooftop antennas', 'A magnetic surge that makes lights turn purple'], 'answer': 0, 'explanation': 'Appliances like TVs, microwaves, game consoles, and phone chargers consume electrical power even when switched off if their plugs remain energized.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Standby Power Consumption:</strong></p>\n                <p class='text-slate-300'>Standby power accounts for up to 10% of total residential electricity bills. Turning off wall switches completely stops this unnecessary drain.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Electricity consumed by appliances left in standby mode)</p>\n            </div>\n        "}, {'id': 38, 'question': 'What certification label on Indian household appliances indicates superior electrical energy efficiency?', 'options': ['BEE Star Rating Label (Bureau of Energy Efficiency, 1 to 5 Stars)', 'A plastic red danger triangle', 'A diamond warranty sticker', 'A golden medal ribbon'], 'answer': 0, 'explanation': 'The Bureau of Energy Efficiency (BEE) rates refrigerators, air conditioners, and fans from 1 to 5 stars; 5-star models consume the least electricity.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>BEE Star Rating Standards:</strong></p>\n                <p class='text-slate-300'>A 5-star inverter air conditioner or refrigerator uses advanced variable-speed compressors, saving up to 30% more power than a 1-star appliance.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (BEE Star Rating Label from 1 to 5 Stars)</p>\n            </div>\n        "}, {'id': 39, 'question': 'Why is drying washed clothes outdoors on a sunny clothesline scientifically wiser than using an electric tumble dryer?', 'options': ['It utilizes free, zero-emission solar radiant and wind energy instead of consuming high-wattage electricity from coal power plants', 'It makes clothes turn completely transparent', 'It takes three weeks for clothes to dry', 'It shrinks clothes to half their size'], 'answer': 0, 'explanation': 'Solar drying uses natural radiant heat and ambient air circulation to evaporate moisture cleanly, while ultraviolet sunlight naturally disinfects fabrics.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Natural Solar Dehydration:</strong></p>\n                <p class='text-slate-300'>Electric tumble dryers consume 2,000 to 4,000 watts per load. Sun drying eliminates this energy footprint and utilizes solar UV rays to kill microbes.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Utilizes free, zero-emission solar and wind energy)</p>\n            </div>\n        "}, {'id': 40, 'question': "What overarching message does Chapter 7 convey about humanity's relationship with energy?", 'options': ['Energy is essential for all life and progress; by embracing clean renewables and active conservation, we secure a prosperous, green planet', 'Humans should stop moving and stay motionless to save energy', 'We should burn all remaining coal as fast as possible', 'Only batteries can provide real energy'], 'answer': 0, 'explanation': 'Energy drives all living systems and modern society. Shifting to renewable sources and practicing daily conservation ensures sustainable planetary survival.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Sustainable Energy Paradigm:</strong></p>\n                <p class='text-slate-300'>Understanding how energy transforms empowers students to become proactive ecological stewards who champion solar, wind, and mindful energy habits.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Embracing clean renewables and active conservation secures a green planet)</p>\n            </div>\n        "}]
